var EM30={id:"EM-30",kind:"Architecture",wide:true,title:"Plain Outside, Starry Inside",object:"Mausoleum of Galla Placidia",playable:true,
 crumb:"Early Medieval Period, circa 300 C.E. \u2013 900 C.E.",
 work:"Mausoleum of Galla Placidia",date:"about 425 C.E.",location:"Ravenna, Italy",artist:"builders unknown; built during the rule of Galla Placidia",
 headline:"Look closely at the building",
 alt:"A small building of reddish-brown brick seen from a corner, on a lawn under a pale sky. Two low wings with triangular gable ends and red tile roofs meet in front of a taller square block that rises behind them. A row of rounded arches is set into the brick walls, most with a narrow slit and none with a door. Tall pine trees stand behind.",
 enlarge:"Enlarge image",
 image:"public/images/artworks/GallaPlacidia-Exterior.jpg",
 imageNote:"",
 detail:{image:"public/images/artworks/GallaPlacidia-Interior.jpg",flex:60,alt:"The inside of one arm of the building. A rounded, tunnel-shaped ceiling is covered in deep blue mosaic scattered with gold stars and flower-like circles. A wide band of green leaves and fruit frames the ceiling, with a small gold cross at its top. Below, a half-circle mosaic shows a seated figure among white sheep.",caption:"Technique detail: inside, a rounded ceiling covered in mosaic stars, with a Good Shepherd mosaic below",credit:{word:"Detail photo (interior)",url:"https://commons.wikimedia.org/wiki/File:Galla_Placidia_Ravenna_05.JPG",author:"Superchilum",license:"CC BY-SA 4.0",licenseUrl:"https://creativecommons.org/licenses/by-sa/4.0/",changes:"Resized from the original."}},
 detail2:{image:"public/images/artworks/GallaPlacidia-Plan.png",flex:40,alt:"A flat black-and-white drawing of a floor plan in the shape of a cross, with four arms drawn in thick black walls and a few small rectangles inside. The label Plan K is printed below.",caption:"Technique detail: a floor plan in the shape of a cross",credit:{word:"Detail (plan)",url:"https://commons.wikimedia.org/wiki/File:Plan_of_Mausoleum_of_Galla_Placidia_(Ravenna)_by_A_history_of_architecture_on_the_comparative_method,_London_1905,_crop_page_181.jpg",author:"Banister Fletcher (crop by Paolo Villa)",license:"Public domain",licenseUrl:"https://creativecommons.org/publicdomain/mark/1.0/",changes:"Cropped and converted to PNG."}},
 size:"",
 intro:"This small brick building in Ravenna, Italy, was built about 1,600 years ago as a mausoleum. From the outside it looks like plain brickwork — but inside, every surface glows with mosaics. Why might the builders have hidden all that richness behind such a simple exterior?",
 context:[{term:"Mausoleum",def:"a building made to hold one or more tombs. This one was built for the empress Galla Placidia"},{term:"Blind arch",def:"an arch set into a wall with no opening behind it. Here they decorate the brick exterior"},{term:"Cruciform",def:"shaped like a cross. The floor plan shows this building's cruciform layout"}],
 clues:[{id:"blind",label:"Blind arches",def:"Arches set into the brick walls with no opening behind them"},{id:"gable",label:"Gable ends",def:"The triangular shape where each wing's walls meet the sloped roof"},{id:"tower",label:"Square tower",def:"A tall, square block of brick rising above the lower wings"}],
 steps:["Click a feature box below, then click where you identify the feature on the image. Identify all three features.",{head:"Choose two.",body:"Write at least one sentence about the feature. Try to use a Word to Know."}],
 closing:"The outside is plain brick, but the inside glitters with mosaic. Why might a builder keep the outside simple and save the richest decoration for inside?",
 bonus:{points:5,prompt:"For 5 bonus points, add any additional observations about the work in general, or question(s) you would like to pursue later.",placeholder:""},
 guide:"Evidence filed. Blind arches, gable ends and a square tower are features a detective can carry to the next case.",
 sourceNums:[73,74,75],
 credit:{word:"Photo",url:"https://commons.wikimedia.org/wiki/File:Mausoleum_of_Galla_Placidia_in_Ravenna.JPG",author:"Petar Milo\u0161evi\u0107",license:"CC BY-SA 4.0",licenseUrl:"https://creativecommons.org/licenses/by-sa/4.0/",changes:"Resized from the original."}};
