var LM02={id:"LM-02",kind:"Embroidery",wide:true,title:"Stitched in Wool",object:"A scene from the Bayeux Tapestry",playable:true,
 crumb:"Late Medieval Period, circa 900 C.E. \u2013 1400 C.E.",
 work:"The Bayeux Tapestry (battle scenes)",date:"made in the 1070s C.E.",location:"Bayeux Tapestry Museum, Bayeux, France",artist:"Artists unknown",
 headline:"Look closely at how it is made",
 alt:"A section of an embroidered band showing a battle, photographed in warm light. On the left, mounted soldiers in dotted mail shirts ride red, brown and dark horses past fallen figures. On the right, a row of soldiers on foot stand behind a line of tall kite-shaped shields. Narrow strips above and below the scene hold small animals, diagonal stripes and fallen soldiers, and a few Latin letters are stitched at the upper left.",
 enlarge:"Enlarge image",
 image:"public/images/artworks/Bayeux-Hastings-Band.jpg",
 imageNote:"",
 detail:{image:"public/images/artworks/Bayeux-Scene55-Eustace.jpg",alt:"A close view of embroidered cloth. A rider in a pointed helmet and a shirt of ring-patterned mail stretches one arm out to point. He sits on a deep blue horse, with a second, tan horse beside it. Latin letters are stitched into the empty space around them, and a banner with a cross flies near the top. The threads are blue, rust-red and tan on pale linen.",caption:"Technique detail: up close, the colors are filled with rows of tiny stitches, and each shape is edged with a darker thread",credit:{word:"Detail photo (scene 55)",url:"https://commons.wikimedia.org/wiki/File:Bayeux_Tapestry_scene55_Eustach.jpg",author:"Myrabella",license:"CC0 1.0",licenseUrl:"https://creativecommons.org/publicdomain/zero/1.0/",changes:"Resized from the original."}},
 size:"The whole band is about 70 m / 230 ft long but only about 50 cm / 20 in tall. Longer than two basketball courts.",
 intro:"Almost 1,000 years ago, a story was sewn onto a long band of linen in colored wool. Look closely at how the picture is made. Can you find three features?",
 context:"Embroidery is a picture or pattern sewn onto cloth with needle and thread. The Bayeux Tapestry is an embroidery, not a woven tapestry.",
 clues:[{id:"outlines",label:"Outlined shapes",def:"Shapes edged in dark thread and filled in with flat color"},{id:"borders",label:"Border bands",def:"Narrow strips above and below the main scene, filled with small animals and patterns"},{id:"rings",label:"Ring pattern",def:"Armor drawn as rows of small repeating ovals"}],
 steps:["Click a feature box below, then click where you identify the feature on the image. Identify all three features.","Choose any two features to write about. For each, write at least one sentence about your own observations or what you find most interesting."],
 closing:"Every figure is outlined and filled with flat color, and strips of animals frame the story above and below. What does this way of making a picture do well when the story runs along a band about 70 meters long?",
 bonus:{points:5,prompt:"For 5 bonus points, add any additional observations about the work in general, or question(s) you would like to pursue later.",placeholder:""},
 guide:"Evidence filed. Outlined shapes, border bands and a ring pattern are features a detective can carry to the next case.",
 sourceNums:[83],
 credit:{word:"Photo",url:"https://commons.wikimedia.org/wiki/File:Bayeux_Tapestry_4.jpg",author:"Gabriel Seah",license:"Public domain",licenseUrl:"",changes:"Cropped to the embroidered band."}};
