var LM05={id:"LM-05",kind:"Relief sculpture",wide:true,title:"Framed in Stone",object:"Annunciation relief at Conques",playable:true,
 crumb:"Late Medieval Period, circa 900 C.E. – 1400 C.E.",
 work:"Annunciation relief",date:"early 12th century C.E.",location:"Abbey Church of Sainte-Foy, Conques, France",artist:"Artist unknown",
 headline:"Look closely at the wall",
 alt:"Part of an old stone wall inside a church, seen up close. Two tall arched windows stand at the left and right, each framed by rings of wedge-shaped stones. Between and above them, a carved block holds two small standing figures under little arches. Thin red lines run along the joints between the wall stones.",
 enlarge:"Enlarge image",
 image:"public/images/artworks/Conques-Interior.jpg",
 imageNote:"",
 detail:{image:"public/images/artworks/Conques-Detail.jpg",alt:"A close view of the carved block. Two figures stand side by side, each under a small round arch with a flat disk behind the head. On the left, a winged figure leans forward and points, holding a scroll with letters. On the right, a woman in a long robe raises one hand. Slim columns with leafy tops separate and frame them. Above them, the stone is carved as a wall with notched battlements and rows of small blocks.",caption:"Technique detail: up close, one figure leans forward to point while the other raises a hand, and their robes fall in soft folds",credit:{word:"Detail photo (relief)",url:"https://commons.wikimedia.org/wiki/File:Conques_-_Abbatiale_Sainte-Foy_-_131.jpg",author:"Antoine Garnier",license:"CC BY-SA 4.0",licenseUrl:"https://creativecommons.org/licenses/by-sa/4.0/",changes:"Resized from the original."}},
 size:"",
 intro:"Almost 900 years ago, a sculptor carved this scene — an angel speaking to a young woman — into a block of stone and set it into a church wall. Instead of standing stiff and square, the two figures lean toward each other and gesture with their hands. Why would an artist want his figures to move and turn like real people?",
 context:[{term:"Voussoir",pron:"VOO-swar",def:"a wedge-shaped stone used to build an arch. Laid side by side, voussoirs form a curved ring."},{term:"Annunciation",pron:"",def:"the Christian Bible scene shown here: the angel Gabriel visiting Mary. It appears in art again and again across the centuries."},{term:"Relief",pron:"rih-LEEF",def:"carving that rises from a flat background instead of standing free."}],
 clues:[{id:"arches",label:"Rings of arch stones",def:"Wedge-shaped stones laid side by side to form curved rings above the windows"},{id:"frame",label:"Figures framed by columns",def:"Two people carved in one block, standing between slim columns under small arches"},{id:"pose",label:"Bodies that lean and turn",def:"Figures that bend forward, shift their weight and raise a hand, instead of standing stiff and square"}],
 steps:["Click a feature box below, then click where you identify the feature on the image. Identify all three features.","Choose any two features to write about. For each, write at least one sentence about your own observations or what you find most interesting."],
 closing:"Gabriel leans toward Mary, and Mary raises a hand. How does their way of standing help tell the story, compared with figures who stand stiff and square?",
 bonus:{points:5,prompt:"For 5 bonus points, add any additional observations about the work in general, or question(s) you would like to pursue later.",placeholder:""},
 guide:"Evidence filed. Rings of arch stones, figures framed by columns and bodies that lean and turn are features a detective can carry to the next case.",
 sourceNums:[90,91],
 credit:{word:"Photo",url:"https://commons.wikimedia.org/wiki/File:Conques_-_Abbatiale_Sainte-Foy_10.jpg",author:"Christophe.Finot",license:"CC BY-SA 2.5",licenseUrl:"https://creativecommons.org/licenses/by-sa/2.5/",changes:"Resized from the original."}};
