 context:[{term:"Maestà",pron:"my-ess-TAH",def:"a picture of the Virgin and Child enthroned in majesty, often surrounded by angels and saints."},{term:"Tempera",pron:"TEM-puh-ruh",def:"egg-based paint used on wood panels for most Italian paintings before oil paint arrived."},{term:"Prophet",pron:"PROF-it",def:"in the Bible, a person who speaks God’s message. Here, four prophets hold scrolls under the throne."}],
