 imageNote:"",
 detail:{image:"public/images/artworks/Giotto-Angels-Detail.jpg",flex:40,alt:"A close view of angels in a deep blue sky, each with a gold nimbus and golden wings. One dives headfirst with arms spread wide, and another presses both hands to its cheeks with a face twisted in tears.",caption:"Technique detail: close up, angels dive through the sky, and one presses both hands to a crying face",credit:{"word": "Detail photo", "url": "https://commons.wikimedia.org/wiki/File:Giotto_di_Bondone_-_No._36_Scenes_from_the_Life_of_Christ_-_20._Lamentation_((detail)_-_WGA09223.jpg", "author": "Giotto di Bondone (painter); reproduction image from the Web Gallery of Art", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "changes": "Shown at its original size."}},
