var LM18={id:"LM-18",kind:"Stone relief",wide:true,title:"Long Bodies, an Almond Frame and Bands",object:"Last Judgment Tympanum, Autun Cathedral",playable:true,
 crumb:"Late Medieval Period, circa 900 C.E. \u2013 1400 C.E.",
 work:"Last Judgment Tympanum",date:"c. 1130\u20131146 C.E.",location:"Cathedral of Saint-Lazare, Autun, France",artist:"Artist unknown",
 headline:"Look closely at the doorway",
 alt:"A tall stone church doorway under a rounded arch, with two dark wooden doors and a single tall statue standing between them. Above the doors, a half-circle of crowded carving shows one large figure seated inside an almond-shaped frame, with smaller figures in bands on each side and a row of slim figures along the bottom. Wide arches of carved circles and leafy scrolls surround the half-circle.",
 enlarge:"Enlarge image",
 image:"public/images/artworks/Autun-Portal.jpg",
 imageNote:"The half-circle of carving above the doors is called the tympanum (TIM-puh-num). Christ’s head was cut off in the 1700s and put back in place in 1948.",
 detail:{image:"public/images/artworks/Autun-Lintel.jpg",flex:50,alt:"A close view of the lower left part of the carving. A row of slim standing figures, some holding tall curved staffs, fills the bottom band, with a line of Latin letters carved above it. In the band above, bare figures stand among robed figures and an angel with large wings.",caption:"Technique detail: close up, slim figures with long limbs standing in a row inside a carved band",credit:{"word": "Detail photo (figures)", "url": "https://commons.wikimedia.org/wiki/File:Autun,_Cath%C3%A9drale_Saint-Lazare_PM_48394.jpg", "author": "PMRMaeyaert", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "changes": "Shown at its original size."}},
 detail2:{image:"public/images/artworks/Autun-Arch.jpg",flex:50,alt:"A close view of part of the carved arch around the tympanum. A row of round frames holds fish, a bull and other animals, with leafy plants between them. Below it, a band of thick scrolling vines with leaves curls along the arch, and a real pigeon perches on the stone.",caption:"Technique detail: close up, small animals carved inside round frames, with a band of leafy scrolls below",credit:{"word": "Detail photo (arch)", "url": "https://commons.wikimedia.org/wiki/File:Cathedral_of_St._Lazare,_Autun,_France_--_Relief_sculpture_-_Vanderbilt_ACT_-_Autun35.jpg", "author": "Anne C. Richardson and Jim Womack (Vanderbilt Art in the Christian Tradition)", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "changes": "Resized from the original."}},
 size:"",
 intro:"Almost 900 years ago, a sculptor carved this crowded half-circle of stone above the main door of a French church. Every visitor had to pass under it to enter. Why would a sculptor crowd so many figures over the entrance to a place of worship?",
 context:[{term:"Tympanum",pron:"TIM-puh-num",def:"the carved half-circle of stone above a church doorway."},{term:"Relief",pron:"rih-LEEF",def:"carving that rises from a flat background instead of standing free."},{term:"Mandorla",pron:"man-DOR-la",def:"an almond-shaped frame around a holy figure, used to set that figure apart."}],
 clues:[{id:"stretch",label:"Elongated figures",def:"Tall, slim bodies with long arms and legs, stretched beyond ordinary proportions"},{id:"mandorla",label:"Central mandorla",def:"One large figure seated inside an almond-shaped frame (a mandorla), which sets him apart from everyone else"},{id:"bands",label:"Stacked bands",def:"Figures arranged in horizontal rows, with one band stacked above another"}],
 steps:["Click a feature box below, then click where you identify the feature on the image. Identify all three features.","Choose any two features to write about. For each, write at least one sentence about your own observations or what you find most interesting."],
 closing:"Compare the almond frame around Christ here with the one in the Taüll painting. How does each artist, one in paint and one in stone, show that this figure matters most?",
 bonus:{points:5,prompt:"For 5 bonus points, add any additional observations about the work in general, or question(s) you would like to pursue later.",placeholder:""},
 guide:"Evidence filed. Stretched bodies, an almond frame around the main figure and figures in bands are features a detective can carry to the next case.",
 sourceNums:[112,113],
 credit:{"word": "Photo", "url": "https://commons.wikimedia.org/wiki/File:Autun_-_Cath%C3%A9drale_Saint-Lazare_-_Portail_principal_-_01.jpg", "author": "Benjamin Smith", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "changes": "Resized from the original."}};
