var LM22={id:"LM-22",kind:"Architecture",title:"Stretched Arches, Thin Piers and Doubled Supports",object:"Choir of Beauvais Cathedral",playable:true,
 crumb:"Late Medieval Period, circa 900 C.E. \u2013 1400 C.E.",
 work:"Choir of the Cathedral of Saint-Pierre",date:"begun 1225 C.E.; the vault fell in 1284",location:"Beauvais, France",artist:"Architect unknown",
 headline:"Look closely at the supports and the arches",
 alt:"A view into the tall choir of a stone church. Very slender stone supports rise from the floor and run up past the top of the picture without a break. Behind them stand tall, narrow pointed arches, far taller than they are wide. Above those runs a band of small arches, and above that are rows of stained-glass windows in blue, red and white. An altar with yellow cloth stands at the centre, with rows of wooden chairs in front of it.",
 enlarge:"Enlarge image",
 image:"public/images/artworks/Beauvais-Choir.jpg",
 imageNote:"The photograph cannot hold the whole height: the ceiling is above the top edge of the picture.",
 detail:{image:"public/images/artworks/Beauvais-Piers.jpg",flex:45,alt:"A close view of four slender stone supports standing in two close pairs. Between and behind them rise very tall narrow pointed arches. A band of small arches on short columns runs across the middle, and bright stained-glass windows with circular patterns glow above and below it.",caption:"Technique detail: slender piers standing in close pairs, added after the collapse",credit:{"word": "Detail photo (piers)", "url": "https://commons.wikimedia.org/wiki/File:Beauvais_Cath%C3%A9drale_Saint-Pierre_Innen_Chor_3.jpg", "author": "Zairon", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "changes": "Cropped and resized from the original."}},
 detail2:{image:"public/images/artworks/Beauvais-Buttresses.jpg",flex:55,alt:"The outside of the cathedral seen from above the rooftops of the town. Rows of tall stone piers stand away from the building, each capped with a pointed spire. Arched stone props spring from the tops of these piers across to the upper wall. Between them rise tall windows filled with stone tracery, and a large round rose window fills the end wall. A grey roof runs along the top.",caption:"Structure detail: the flying buttresses outside, the arched props that carry the push of the vault down to the ground. The ones standing in 1284 twisted and broke.",credit:{"word": "Detail photo (buttresses)", "url": "https://commons.wikimedia.org/wiki/File:Cath%C3%A9drale_Saint-Pierre_de_Beauvais_(1).jpg", "author": "Baidax", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "changes": "Resized from the original."}},
 size:"The choir vault stands about 47 m / 155 ft above the floor, the tallest Gothic stone vault ever built.",
 intro:"The builders here tried to go higher than anyone had gone before, and in 1284 the ceiling fell. Can you find three features?",
 context:"A pier (PEER) is an upright support, thicker than a column, that carries the weight of what stands above it.",
 clues:[{"id": "doubled", "label": "Doubled supports", "def": "Piers standing in close pairs, where a single pier would usually stand alone"}, {"id": "stretched", "label": "Stretched arches", "def": "Pointed arches pulled far taller than they are wide"}, {"id": "smallarches", "label": "Band of small arches", "def": "A narrow row of small arches running across the wall, between the tall arches below and the windows above"}],
 steps:["Click a feature box below, then click where you identify the feature on the image. Identify all three features.", "Choose any two features to write about. For each, write at least one sentence about your own observations or what you find most interesting."],
 closing:"Compare this choir with Chartres. Both use the same ideas, but Beauvais pushes them further than the stone could bear. When builders added the extra piers, what did they gain, and what did they give up?",
 bonus:{points:5,prompt:"For 5 bonus points, add any additional observations about the work in general, or question(s) you would like to pursue later.",placeholder:""},
 guide:"Evidence filed. Doubled supports, stretched arches and a band of small arches are features a detective can carry to the next case.",
 sourceNums:[120,121],
 credit:{"word": "Photo", "url": "https://commons.wikimedia.org/wiki/File:Beauvais_Cath%C3%A9drale_Saint-Pierre_Innen_Chor_3.jpg", "author": "Zairon", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "changes": "Resized from the original."}};
