var LM23={id:"LM-23",kind:"Timber architecture",wide:true,title:"Stacked Roofs, Dragon Heads and Upright Boards",object:"Borgund Stave Church",playable:true,
 crumb:"Late Medieval Period, circa 900 C.E. \u2013 1400 C.E.",
 work:"Borgund Stave Church",date:"c. 1180\u20131200 C.E.",location:"Borgund, L\u00e6rdal, Norway",artist:"Builders unknown",
 headline:"Look closely at the roofs and the walls",
 alt:"A dark wooden church standing in a grassy graveyard below a green mountain. Its roofs are stacked one above another, each smaller than the one below, rising to a slim tower with a spire. Every roof and much of the wall is covered in small overlapping wooden tiles. Carved animal heads on long necks rise from the roof peaks. Below the roofs the walls are made of upright wooden boards set side by side. Pale gravestones stand in the grass in front.",
 enlarge:"Enlarge image",
 image:"public/images/artworks/Borgund-Church.jpg",
 imageNote:"Coatings of tar have protected the timber for centuries, which is why the wood is almost black.",
 detail:{image:"public/images/artworks/Borgund-Dragons.jpg",flex:55,alt:"A close view of the top of the wooden tower. Two carved animal heads on long curved necks rise from the roof ridges and face outward, their surfaces cut with looping ribbon patterns. Between them a small shingled tower rises to a point, and a square panel below is pierced with carved interlacing vines.",caption:"Technique detail: carved heads and interlace on the tower. The heads in place today may be later replacements.",credit:{"word": "Detail photo (tower)", "url": "https://commons.wikimedia.org/wiki/File:Borgund_stave_church_exterior_20230926-5.jpg", "author": "Bj\u00f8rn Erik Pedersen", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "changes": "Cropped and resized from the original."}},
 detail2:{image:"public/images/artworks/Borgund-Frame.jpg",flex:45,alt:"A view looking straight up inside the church. Heavy timbers cross one another in X shapes between tall upright posts. Round openings are cut through the boards on every side, and carved rosettes mark the joints. The wood glows warm brown and gold where light reaches it.",caption:"Structure detail: the timber frame seen from below, with crossed braces between the staves",credit:{"word": "Detail photo (frame)", "url": "https://commons.wikimedia.org/wiki/File:Borgund_Stave_Church_interior.jpg", "author": "Stevan Nicholas", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "changes": "Cropped and resized from the original."}},
 size:"Built of timber on a stone foundation. The frame is pegged together with more than 11,000 wooden nails and no metal ones.",
 intro:"This church is built entirely of wood, by builders with no stone vaults to copy. Can you find three features?",
 context:"A stave (STAYV) is an upright wooden post. A stave church is built on a frame of staves, with walls of upright boards.",
 clues:[{"id": "roofs", "label": "Stacked roofs", "def": "Roofs set one above another, each smaller than the one below it"}, {"id": "dragons", "label": "Dragon heads", "def": "Carved animal heads rising from the roof peaks, like the prows of Viking ships"}, {"id": "boards", "label": "Upright boards", "def": "Walls made of tall wooden boards standing side by side, not stacked logs"}],
 steps:["Click a feature box below, then click where you identify the feature on the image. Identify all three features.", "Choose any two features to write about. For each, write at least one sentence about your own observations or what you find most interesting."],
 closing:"Compare this with Durham and Chartres. All three had to hold up a roof and keep out the weather. What did timber let these builders do that stone did not?",
 bonus:{points:5,prompt:"For 5 bonus points, add any additional observations about the work in general, or question(s) you would like to pursue later.",placeholder:""},
 guide:"Evidence filed. Stacked roofs, dragon heads and upright boards are features a detective can carry to the next case.",
 sourceNums:[122,123],
 credit:{"word": "Photo", "url": "https://commons.wikimedia.org/wiki/File:Borgund_stavkyrkje_2022c.jpg", "author": "Tulipasylvestris", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "changes": "Resized from the original."}};
